CASE ssMethodType OF
    SS_INITIALIZE: 
        plc_ts_counter1 := 0;
        (* SystemInitialize for Chart: '<Root>/Nivel 1' *)
        temporalCounter_i3(timerAction := 1, maxTime := 0);
        temporalCounter_i1 := 0;
        temporalCounter_i2 := 0;
        (* '<S1>:310:7' last_i_ref = -1; *)
        last_i_ref := -1.0;
        b_BRK_h_N1 := 0.0;
        b_BRK_t_N1 := 0.0;
        dead_zone := 0.0;
        b_TLK := 0.0;
        hay_cont := 0.0;
        y_start := 0.0;
        (* SystemInitialize for Chart: '<Root>/Nivel 1' *)

        FOR i := 0 TO 32 DO 
            b_yc0_vec[i] := 0.0;
        END_FOR;

        TLK_anterior := 0.0;
        i_carro := 0.0;
        vh_lim := 0.0;
        vel_error := 0.0;
        error_der := 0.0;
        error_inf := 0.0;
        error_izq := 0.0;
        error_sup := 0.0;
